session_start();require_once('dbstring.php');require_once('check-login.php');require_once('parent-utils.php');parent_portal_ensure_tables($con);if(!parent_portal_is_admin()){header('location:index.php');exit();}$flash='';
if(isset($_POST['approve_link'])&&parent_portal_csrf_valid($_POST['csrf']??'')){$link=(int)($_POST['linkid']??0);$actor=mysqli_real_escape_string($con,(string)$_SESSION['USERID']);mysqli_query($con,"UPDATE tblparentstudentlink SET status='active',approvedat=NOW(),approvedby='$actor' WHERE linkid=$link AND status='pending'");mysqli_query($con,"UPDATE tblparentaccount pa INNER JOIN tblparentstudentlink pl ON pl.parentid=pa.parentid SET pa.status='active' WHERE pl.linkid=$link AND pl.status='active'");$flash='The parent-child link was approved.';}
if(isset($_POST['reject_link'])&&parent_portal_csrf_valid($_POST['csrf']??'')){$link=(int)($_POST['linkid']??0);mysqli_query($con,"UPDATE tblparentstudentlink SET status='rejected' WHERE linkid=$link AND status='pending'");$flash='The request was rejected.';}
$rows=mysqli_query($con,"SELECT pl.linkid,pl.relationshiptext,pl.requestedat,pa.fullname AS parentname,pa.email,pa.mobile,su.userid,su.firstname,su.othernames,su.surname,su.nextofkin_fullname FROM tblparentstudentlink pl INNER JOIN tblparentaccount pa ON pa.parentid=pl.parentid INNER JOIN tblsystemuser su ON su.userid=pl.studentid WHERE pl.status='pending' ORDER BY pl.requestedat ASC");
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Parent Portal Approvals</title><style>body{margin:0;background:#f3f7fa;color:#1d3042;font:15px Arial}.wrap{max-width:1120px;margin:auto;padding:30px 18px}.hero{padding:26px;border-radius:17px;background:linear-gradient(120deg,#163656,#08766f);color:#fff}.hero h1{margin:5px 0;font:600 30px Georgia}.hero a{color:#fff}.flash{padding:13px;background:#e6f7ef;color:#126443;border-radius:8px;margin-top:15px}.panel{margin-top:18px;background:#fff;border:1px solid #d7e2ea;border-radius:14px;padding:20px;overflow:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:12px;border-bottom:1px solid #e5edf2;vertical-align:top}th{color:#163656;background:#f2f7f8}button{border:0;border-radius:7px;padding:9px 11px;color:#fff;background:#08766f;font-weight:bold;cursor:pointer}.reject{background:#9d3038}.empty{color:#637789}</style></head><body><main class="wrap"><section class="hero"><a href="admin.php">← Admin dashboard</a><h1>Parent Portal approvals</h1><p>Approve only after confirming the adult and child relationship with the school record.</p></section><?php if($flash){?><p class="flash"><?php echo parent_portal_safe($flash);?></p><?php }?><section class="panel"><table><thead><tr><th>Parent / guardian</th><th>Requested child</th><th>Relationship</th><th>Requested</th><th>Action</th></tr></thead><tbody><?php if($rows&&mysqli_num_rows($rows)){while($row=mysqli_fetch_assoc($rows)){$student=trim($row['firstname'].' '.$row['othernames'].' '.$row['surname']);?><tr><td><b><?php echo parent_portal_safe($row['parentname']);?></b><br><?php echo parent_portal_safe($row['email']);?><br><?php echo parent_portal_safe($row['mobile']);?></td><td><b><?php echo parent_portal_safe($student);?></b><br><?php echo parent_portal_safe($row['userid']);?><br>School guardian: <?php echo parent_portal_safe($row['nextofkin_fullname']);?></td><td><?php echo parent_portal_safe($row['relationshiptext']);?></td><td><?php echo parent_portal_safe($row['requestedat']);?></td><td><form method="post"><input type="hidden" name="csrf" value="<?php echo parent_portal_safe(parent_portal_csrf());?>"><input type="hidden" name="linkid" value="<?php echo (int)$row['linkid'];?>"><button name="approve_link">Approve</button> <button class="reject" name="reject_link" onclick="return confirm('Reject this request?')">Reject</button></form></td></tr><?php }}else{?><tr><td class="empty" colspan="5">No parent access requests are waiting for approval.</td></tr><?php }?></tbody></table></section></main></body></html>
